import {
  BLOCKED_STAMINA_PENALTY,
  ENCOURAGE_BONUS,
  REACH_DIFFICULTY_BONUS,
  REST_HOLD_RECOVERY,
  REST_RECOVERY,
  ROPE_CONSUMED,
  RUNOUT_THRESHOLD,
  STAMINA_COST,
  TEAMWORK_ROLL_BONUS,
  TEAMWORK_ROPE_BONUS,
} from './config.ts';
import { blockReason } from './legality.ts';
import { difficultyAt, isRestHold } from './routes.ts';
import type {
  BelayerAction,
  BlockReason,
  ClimberAction,
  FallCause,
  FallDetail,
  GameConfig,
  GameStatus,
  LossReason,
  RollDetail,
  RouteDefinition,
} from './types.ts';

/**
 * The minimal state the rules act on. `resolveRound` wraps this with history and statistics;
 * the AI planner and balance simulator call `stepCore` directly for speed. There is exactly one
 * implementation of the rules: this function.
 */
export interface CoreState {
  position: number;
  stamina: number;
  rope: number;
  lastClippedPosition: number;
  clippedBolts: readonly number[];
  recoveryTokens: number;
  teamworkAvailable: boolean;
  round: number;
  status: GameStatus;
}

export interface TeamworkPermissions {
  rescue: boolean;
  convert: boolean;
}

export interface CoreStepDetail {
  ropeAfterBelay: number;
  legal: boolean;
  blockedReason: BlockReason | null;
  teamwork: 'RESCUE' | 'CONVERT' | null;
  roll: RollDetail | null;
  fall: FallDetail | null;
  clipped: number | null;
  restedOnRestHold: boolean | null;
  outcome: 'moved' | 'fell' | 'clipped' | 'rested' | 'blocked' | 'summit';
  endReason: LossReason | 'summit' | null;
}

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

export function stepCore(
  s: CoreState,
  route: RouteDefinition,
  cfg: GameConfig,
  climber: ClimberAction,
  belayer: BelayerAction,
  teamworkOk: TeamworkPermissions,
  rollDie: () => number,
): { next: CoreState; detail: CoreStepDetail } {
  const next: CoreState = { ...s };

  // 1. Belayer card resolves first.
  let rope = s.rope;
  if (belayer === 'FEED') rope = clamp(rope + 1, cfg.ropeMin, cfg.ropeMax);
  if (belayer === 'TAKE_IN') rope = clamp(rope - 1, cfg.ropeMin, cfg.ropeMax);
  const ropeAfterBelay = rope;

  // 2. Legality, with an optional Teamwork rescue (adds rope only).
  let teamwork: CoreStepDetail['teamwork'] = null;
  let reason = blockReason(s, route, climber, rope);
  if (
    reason === 'not_enough_rope' &&
    s.teamworkAvailable &&
    teamworkOk.rescue &&
    blockReason(s, route, climber, rope + TEAMWORK_ROPE_BONUS) === null
  ) {
    rope = clamp(rope + TEAMWORK_ROPE_BONUS, cfg.ropeMin, cfg.ropeMax);
    teamwork = 'RESCUE';
    reason = null;
  }

  let roll: RollDetail | null = null;
  let fall: FallDetail | null = null;
  let clipped: number | null = null;
  let restedOnRestHold: boolean | null = null;
  let outcome: CoreStepDetail['outcome'];

  if (reason !== null) {
    // 3a. Blocked / invalid: lose 1 stamina, no movement, no roll, no fall.
    next.stamina = Math.max(0, s.stamina - BLOCKED_STAMINA_PENALTY);
    outcome = 'blocked';
  } else {
    // 3b. Stamina is paid before anything else.
    next.stamina = s.stamina - STAMINA_COST[climber];
    if (climber === 'REST') {
      restedOnRestHold = isRestHold(route, s.position);
      next.stamina = Math.min(cfg.maxStamina, next.stamina + (restedOnRestHold ? REST_HOLD_RECOVERY : REST_RECOVERY));
      outcome = 'rested';
    } else if (climber === 'CLIP') {
      rope -= ROPE_CONSUMED.CLIP;
      next.clippedBolts = [...s.clippedBolts, s.position].sort((a, b) => a - b);
      next.lastClippedPosition = s.position;
      clipped = s.position;
      outcome = 'clipped';
    } else {
      const destination = s.position + (climber === 'STEP' ? 1 : 2);
      const target =
        difficultyAt(route, destination) + (climber === 'REACH' ? (cfg.reachDifficultyBonus ?? REACH_DIFFICULTY_BONUS) : 0);
      const die = rollDie();
      if (!Number.isInteger(die) || die < 1 || die > 6) throw new Error(`dice returned invalid roll ${die}`);
      const encourageBonus = belayer === 'ENCOURAGE' ? ENCOURAGE_BONUS : 0;
      let adjusted = die + encourageBonus;
      let teamworkBonus = 0;
      // 4. Teamwork "convert": only when +1 turns this exact failure into a success.
      if (
        adjusted < target &&
        teamwork === null &&
        s.teamworkAvailable &&
        teamworkOk.convert &&
        adjusted + TEAMWORK_ROLL_BONUS >= target
      ) {
        teamworkBonus = TEAMWORK_ROLL_BONUS;
        adjusted += teamworkBonus;
        teamwork = 'CONVERT';
      }
      const success = adjusted >= target;
      roll = { die, encourageBonus, teamworkBonus, adjusted, target, destination, success };
      if (success) {
        next.position = destination;
        rope -= ROPE_CONSUMED[climber];
        outcome = destination >= route.length ? 'summit' : 'moved';
      } else {
        // Fall. Stamina already paid; the failed move consumes no rope.
        const causes: FallCause[] = [];
        if (rope === cfg.ropeMax) causes.push('rope_slack');
        if (s.position - s.lastClippedPosition >= RUNOUT_THRESHOLD) causes.push('runout');
        const extraLoss: 0 | 1 = causes.length > 0 ? 1 : 0;
        const minimumLoss = cfg.minimumFallLoss ?? 1;
        const bracePrevented: 0 | 1 = belayer === 'BRACE' && (extraLoss === 1 || minimumLoss === 0) ? 1 : 0;
        const totalLoss = Math.max(minimumLoss, 1 + extraLoss - bracePrevented);
        const returnTo = Math.max(0, s.lastClippedPosition, s.position - 1);
        fall = {
          baseLoss: 1,
          causes,
          extraLoss,
          bracePrevented,
          totalLoss,
          from: s.position,
          lastClipped: s.lastClippedPosition,
          returnTo,
        };
        next.position = returnTo;
        next.recoveryTokens = Math.max(0, s.recoveryTokens - totalLoss);
        outcome = 'fell';
      }
    }
  }

  next.rope = clamp(rope, cfg.ropeMin, cfg.ropeMax);
  if (teamwork !== null) next.teamworkAvailable = false;

  // 5. End of round.
  let endReason: CoreStepDetail['endReason'] = null;
  if (next.position >= route.length) {
    next.status = 'won';
    endReason = 'summit';
  } else if (next.recoveryTokens <= 0) {
    next.status = 'lost';
    endReason = 'out_of_recovery';
  } else if (s.round >= cfg.maxRounds) {
    next.status = 'lost';
    endReason = 'out_of_rounds';
  } else {
    next.round = s.round + 1;
  }

  return {
    next,
    detail: {
      ropeAfterBelay,
      legal: reason === null,
      blockedReason: reason,
      teamwork,
      roll,
      fall,
      clipped,
      restedOnRestHold,
      outcome,
      endReason,
    },
  };
}
