/**
 * Core types for the On Belay rules engine.
 *
 * The engine is pure TypeScript: no React, no Supabase, no browser APIs. Every game mode
 * (online, pass-and-play, solo vs AI, balance simulation) runs through these types.
 */

export type Role = 'climber' | 'belayer';

export const CLIMBER_ACTIONS = ['STEP', 'REACH', 'CLIP', 'REST'] as const;
export type ClimberAction = (typeof CLIMBER_ACTIONS)[number];

export const BELAYER_ACTIONS = ['FEED', 'TAKE_IN', 'BRACE', 'ENCOURAGE'] as const;
export type BelayerAction = (typeof BELAYER_ACTIONS)[number];

export const TEAMWORK_POLICIES = ['NEVER', 'RESCUE_BLOCKED_MOVE', 'CONVERT_FAILED_ROLL_IF_POSSIBLE'] as const;
export type TeamworkPolicy = (typeof TEAMWORK_POLICIES)[number];

export const CLIMBER_SIGNALS = ['MOVING_CAREFULLY', 'BIG_MOVE', 'PLANNING_CLIP', 'NEED_REST', 'NOT_SURE'] as const;
export type ClimberSignal = (typeof CLIMBER_SIGNALS)[number];

export const BELAYER_SIGNALS = [
  'READY_FOR_MOVEMENT',
  'ROPE_AVAILABLE',
  'STAY_STEADY',
  'BE_CAUTIOUS',
  'READY_WHEN_YOU_ARE',
] as const;
export type BelayerSignal = (typeof BELAYER_SIGNALS)[number];

export type Terrain = 'Vertical' | 'Overhang' | 'Technical Face' | 'Slab' | 'Crack' | 'Roof';

export interface RouteTheme {
  /** Sky gradient top / bottom colors used by the SVG wall. */
  skyTop: string;
  skyBottom: string;
  /** Main rock color and its shadow. */
  rock: string;
  rockShadow: string;
  /** Accent used for hold highlights. */
  accent: string;
}

/**
 * A route is pure data. Positions run 0 (ground) to `length` (finishing anchor).
 * `difficulty[i]` is the difficulty of position i + 1.
 */
export interface RouteDefinition {
  id: string;
  name: string;
  grade: string;
  terrain: Terrain;
  description: string;
  flavor: string;
  length: number;
  difficulty: number[];
  restHolds: number[];
  bolts: number[];
  theme: RouteTheme;
  /** Display order in the route collection. */
  order: number;
}

export interface GameConfig {
  maxStamina: number;
  startStamina: number;
  startRope: number;
  ropeMin: number;
  ropeMax: number;
  recoveryTokens: number;
  maxRounds: number;
  teamworkTokens: number;
  /** Rounds needed (or fewer) for the third carabiner. */
  threeCarabinerRounds: number;
  /** Recovery tokens needed (or more) for the second carabiner. */
  twoCarabinerTokens: number;
  /** Balance-testing knobs. Omitted = the specified rule (Reach +1, a fall costs at least 1). */
  reachDifficultyBonus?: number;
  minimumFallLoss?: number;
}

export interface ClimberSubmission {
  role: 'climber';
  action: ClimberAction;
  signal: ClimberSignal | null;
  teamworkPolicy: TeamworkPolicy;
}

export interface BelayerSubmission {
  role: 'belayer';
  action: BelayerAction;
  signal: BelayerSignal | null;
  teamworkPolicy: TeamworkPolicy;
}

export type Submission = ClimberSubmission | BelayerSubmission;

export interface RoundInput {
  climber: ClimberSubmission;
  belayer: BelayerSubmission;
}

/** Public information a player declares before or with their commitment. Never contains the action. */
export interface PublicDeclaration {
  signal: ClimberSignal | BelayerSignal | null;
  teamworkPolicy: TeamworkPolicy;
  committed: boolean;
}

export type GameStatus = 'in_progress' | 'won' | 'lost';
export type LossReason = 'out_of_recovery' | 'out_of_rounds' | 'forfeit';

export interface GameStats {
  falls: number;
  tokensLost: number;
  blockedActions: number;
  rests: number;
  clips: number;
  teamworkUsedRound: number | null;
  teamworkUse: 'RESCUE' | 'CONVERT' | null;
  belayerActionCounts: Record<BelayerAction, number>;
  climberActionCounts: Record<ClimberAction, number>;
}

export interface GameResult {
  outcome: 'won' | 'lost';
  reason: LossReason | 'summit';
  roundsUsed: number;
  carabiners: 0 | 1 | 2 | 3;
}

export interface GameState {
  routeId: string;
  config: GameConfig;
  status: GameStatus;
  /** 1-based round currently being played (or the final round once finished). */
  round: number;
  position: number;
  stamina: number;
  rope: number;
  lastClippedPosition: number;
  clippedBolts: number[];
  recoveryTokens: number;
  teamworkAvailable: boolean;
  stats: GameStats;
  history: TurnResult[];
  result: GameResult | null;
}

export type BlockReason =
  | 'not_enough_rope'
  | 'not_enough_stamina'
  | 'beyond_finish'
  | 'not_at_bolt'
  | 'already_clipped'
  | 'game_over';

export interface RollDetail {
  die: number;
  encourageBonus: number;
  teamworkBonus: number;
  adjusted: number;
  target: number;
  destination: number;
  success: boolean;
}

export type FallCause = 'rope_slack' | 'runout';

export interface FallDetail {
  baseLoss: 1;
  causes: FallCause[];
  extraLoss: 0 | 1;
  bracePrevented: 0 | 1;
  totalLoss: number;
  from: number;
  /** Last clipped position at the moment of the fall (0 = ground). */
  lastClipped: number;
  returnTo: number;
}

export interface TurnResult {
  round: number;
  climber: ClimberSubmission;
  belayer: BelayerSubmission;
  ropeBefore: number;
  ropeAfterBelay: number;
  ropeAfter: number;
  staminaBefore: number;
  staminaAfter: number;
  positionBefore: number;
  positionAfter: number;
  recoveryBefore: number;
  recoveryAfter: number;
  legal: boolean;
  blockedReason: BlockReason | null;
  teamwork: 'RESCUE' | 'CONVERT' | null;
  roll: RollDetail | null;
  fall: FallDetail | null;
  clipped: number | null;
  restedOnRestHold: boolean | null;
  outcome: 'moved' | 'fell' | 'clipped' | 'rested' | 'blocked' | 'summit';
  statusAfter: GameStatus;
}

/** A source of six-sided die rolls. Injected so tests and the server control randomness. */
export interface DiceSource {
  rollD6(): number;
}
