import type { RouteDefinition, Terrain } from './types.ts';

const TERRAINS: readonly Terrain[] = ['Vertical', 'Overhang', 'Technical Face', 'Slab', 'Crack', 'Roof'];

export interface RouteValidationIssue {
  field: string;
  message: string;
}

/**
 * Validate a route definition. New routes are pure data; the engine never needs to change to
 * support them, so everything the engine relies on is checked here.
 */
export function validateRoute(route: RouteDefinition): RouteValidationIssue[] {
  const issues: RouteValidationIssue[] = [];
  const add = (field: string, message: string) => issues.push({ field, message });

  if (!/^[a-z0-9-]{2,40}$/.test(route.id)) add('id', 'must be 2–40 lowercase letters, digits or dashes');
  if (!route.name.trim()) add('name', 'is required');
  if (!route.grade.trim()) add('grade', 'is required');
  if (!TERRAINS.includes(route.terrain)) add('terrain', `must be one of ${TERRAINS.join(', ')}`);
  if (!Number.isInteger(route.length) || route.length < 3 || route.length > 16) {
    add('length', 'must be an integer from 3 to 16');
  }
  if (route.difficulty.length !== route.length) {
    add('difficulty', `must list exactly ${route.length} values (one per position 1..${route.length})`);
  }
  route.difficulty.forEach((d, i) => {
    if (!Number.isInteger(d) || d < 1 || d > 6) add(`difficulty[${i}]`, 'must be an integer from 1 to 6');
  });
  const checkPositions = (field: 'restHolds' | 'bolts') => {
    const seen = new Set<number>();
    for (const p of route[field]) {
      if (!Number.isInteger(p) || p < 1 || p >= route.length) {
        add(field, `position ${p} must be between 1 and ${route.length - 1} (not the ground or the anchor)`);
      }
      if (seen.has(p)) add(field, `position ${p} is listed twice`);
      seen.add(p);
    }
  };
  checkPositions('restHolds');
  checkPositions('bolts');
  for (const key of ['skyTop', 'skyBottom', 'rock', 'rockShadow', 'accent'] as const) {
    if (!/^#[0-9a-fA-F]{6}$/.test(route.theme[key])) add(`theme.${key}`, 'must be a #rrggbb color');
  }
  return issues;
}

export function assertValidRoute(route: RouteDefinition): RouteDefinition {
  const issues = validateRoute(route);
  if (issues.length) {
    throw new Error(`Invalid route "${route.id}": ${issues.map((i) => `${i.field} ${i.message}`).join('; ')}`);
  }
  return route;
}

/** Difficulty of a position (1-based). Position 0 is the ground and has no difficulty. */
export function difficultyAt(route: RouteDefinition, position: number): number {
  const d = route.difficulty[position - 1];
  if (d === undefined) throw new Error(`No difficulty for position ${position} on ${route.id}`);
  return d;
}

export const isBolt = (route: RouteDefinition, position: number) => route.bolts.includes(position);
export const isRestHold = (route: RouteDefinition, position: number) => route.restHolds.includes(position);
