import { stepCore, type CoreState, type TeamworkPermissions } from '../core.ts';
import {
  BELAYER_ACTIONS,
  CLIMBER_ACTIONS,
  type BelayerAction,
  type ClimberAction,
  type GameConfig,
  type RouteDefinition,
} from '../types.ts';

/**
 * Exact expectimax planner for the cooperative game.
 *
 * `value(s)` is the best achievable expected score from state `s` if both partners coordinated
 * perfectly (the "team optimum"). AI partners combine it with a belief about what the human will
 * do — built only from public information — to pick their own card.
 *
 * Score: 1 for reaching the anchor (+ small bonuses for carabiners), 0 for failing.
 */

export const PERMISSION_OPTIONS: readonly TeamworkPermissions[] = [
  { rescue: false, convert: false },
  { rescue: true, convert: false },
  { rescue: false, convert: true },
  { rescue: true, convert: true },
];
const NO_TEAMWORK = [PERMISSION_OPTIONS[0]!];

const CARABINER_BONUS = 0.04;
const DICE = [1, 2, 3, 4, 5, 6] as const;

export class Planner {
  private readonly memo = new Map<number, number>();
  private readonly qMemo = new Map<number, { value: number; fall: number }>();
  private readonly boltIndex: Map<number, number>;
  readonly route: RouteDefinition;
  readonly cfg: GameConfig;

  constructor(route: RouteDefinition, cfg: GameConfig) {
    this.route = route;
    this.cfg = cfg;
    this.boltIndex = new Map(route.bolts.map((b, i) => [b, i]));
  }

  get cacheSize() {
    return this.memo.size;
  }

  key(s: CoreState): number {
    let mask = 0;
    for (const b of s.clippedBolts) mask |= 1 << (this.boltIndex.get(b) ?? 0);
    // Mixed-radix packing; all fields are small non-negative integers.
    let k = s.round;
    k = k * 32 + s.position;
    k = k * 32 + s.stamina;
    k = k * 8 + s.rope;
    k = k * 32 + s.lastClippedPosition;
    k = k * 256 + mask;
    k = k * 16 + s.recoveryTokens;
    k = k * 2 + (s.teamworkAvailable ? 1 : 0);
    return k;
  }

  terminalScore(s: CoreState): number {
    if (s.status !== 'won') return 0;
    let score = 1;
    if (s.recoveryTokens >= this.cfg.twoCarabinerTokens) score += CARABINER_BONUS;
    if (s.recoveryTokens === this.cfg.recoveryTokens && s.round <= this.cfg.threeCarabinerRounds) score += CARABINER_BONUS;
    return score;
  }

  /** Probability-weighted next states for one joint choice. */
  outcomes(s: CoreState, c: ClimberAction, b: BelayerAction, perms: TeamworkPermissions) {
    let rolled = false;
    const first = stepCore(s, this.route, this.cfg, c, b, perms, () => {
      rolled = true;
      return 1;
    });
    if (!rolled) return [{ p: 1, next: first.next, fell: false }];
    const out: { p: number; next: CoreState; fell: boolean }[] = [{ p: 1 / 6, next: first.next, fell: !!first.detail.fall }];
    for (let i = 1; i < DICE.length; i++) {
      const die = DICE[i]!;
      const r = stepCore(s, this.route, this.cfg, c, b, perms, () => die);
      out.push({ p: 1 / 6, next: r.next, fell: !!r.detail.fall });
    }
    return out;
  }

  /** Expected value of a joint choice. Also returns the probability of a fall. */
  q(s: CoreState, c: ClimberAction, b: BelayerAction, perms: TeamworkPermissions): { value: number; fall: number } {
    const qk =
      ((this.key(s) * 4 + CLIMBER_ACTIONS.indexOf(c)) * 4 + BELAYER_ACTIONS.indexOf(b)) * 4 +
      (perms.rescue ? 1 : 0) +
      (perms.convert ? 2 : 0);
    const hit = this.qMemo.get(qk);
    if (hit) return hit;
    const r = this.computeQ(s, c, b, perms);
    if (this.qMemo.size < 3_000_000) this.qMemo.set(qk, r);
    return r;
  }

  private computeQ(s: CoreState, c: ClimberAction, b: BelayerAction, perms: TeamworkPermissions) {
    let value = 0;
    let fall = 0;
    for (const o of this.outcomes(s, c, b, perms)) {
      value += o.p * this.value(o.next);
      if (o.fell) fall += o.p;
    }
    return { value, fall };
  }

  permissionOptions(s: CoreState): readonly TeamworkPermissions[] {
    return s.teamworkAvailable ? PERMISSION_OPTIONS : NO_TEAMWORK;
  }

  /** Team-optimal value of a state. */
  value(s: CoreState): number {
    if (s.status !== 'in_progress') return this.terminalScore(s);
    const k = this.key(s);
    const cached = this.memo.get(k);
    if (cached !== undefined) return cached;
    let best = 0;
    for (const c of CLIMBER_ACTIONS) {
      for (const b of BELAYER_ACTIONS) {
        for (const perms of this.permissionOptions(s)) {
          const v = this.computeQ(s, c, b, perms).value;
          if (v > best) best = v;
        }
      }
    }
    this.memo.set(k, best);
    return best;
  }

  /** Q-values for every joint choice, best teamwork permission per pair. */
  jointTable(s: CoreState): { c: ClimberAction; b: BelayerAction; value: number; fall: number }[] {
    const rows: { c: ClimberAction; b: BelayerAction; value: number; fall: number }[] = [];
    for (const c of CLIMBER_ACTIONS) {
      for (const b of BELAYER_ACTIONS) {
        let best = { value: -1, fall: 0 };
        for (const perms of this.permissionOptions(s)) {
          const r = this.q(s, c, b, perms);
          if (r.value > best.value) best = r;
        }
        rows.push({ c, b, ...best });
      }
    }
    return rows;
  }
}

const planners = new Map<string, Planner>();

/** Shared planner per route + config; the value cache is reused across games. */
export function plannerFor(route: RouteDefinition, cfg: GameConfig): Planner {
  const key = `${route.id}|${JSON.stringify(route.difficulty)}|${route.bolts}|${route.restHolds}|${JSON.stringify(cfg)}`;
  let p = planners.get(key);
  if (!p) {
    p = new Planner(route, cfg);
    planners.set(key, p);
  }
  return p;
}
