/// <reference lib="webworker" />
import { runAiTask, type AiTask } from './localGame.ts';

/** AI partner worker: keeps the planner's value cache warm across decisions, off the UI thread. */
self.onmessage = (e: MessageEvent<{ id: number; task: AiTask }>) => {
  const { id, task } = e.data;
  try {
    (self as unknown as Worker).postMessage({ id, answer: runAiTask(task) });
  } catch (err) {
    (self as unknown as Worker).postMessage({ id, error: String(err) });
  }
};
