import type { CoreState, TeamworkPermissions } from '../core.ts';
import { structurallyBlocked } from '../legality.ts';
import {
  BELAYER_ACTIONS,
  CLIMBER_ACTIONS,
  TEAMWORK_POLICIES,
  type BelayerAction,
  type BelayerSignal,
  type ClimberAction,
  type ClimberSignal,
  type TeamworkPolicy,
} from '../types.ts';
import { partnerBelayerSignal, partnerClimberSignal, type PublicView } from '../view.ts';
import { plannerFor, type Planner } from './planner.ts';
import { BELAYER_SIGNAL_LIKELIHOOD, CLIMBER_SIGNAL_LIKELIHOOD, bestBelayerSignal, bestClimberSignal } from './signals.ts';

export type AiDifficulty = 'beginner' | 'intermediate' | 'expert';

export interface AiOptions {
  difficulty: AiDifficulty;
  /**
   * Climber risk tolerance from 0 (very cautious) to 1 (bold). 0.5 is neutral: the planner's
   * pure expected value. Below 0.5 penalises falls; above 0.5 rewards progress.
   */
  riskTolerance?: number;
  /** Source of randomness for imperfect (intermediate) play. */
  random: () => number;
}

export interface AiDecision<A, S> {
  action: A;
  signal: S;
  teamworkPolicy: TeamworkPolicy;
  /** Short explanation for debugging and the "why did my partner do that" tooltip. */
  reasoning: string;
}

const RATIONAL_TEMPERATURE = 0.05;
const INTERMEDIATE_TEMPERATURE = 0.008;

function permsFor(a: TeamworkPolicy, b: TeamworkPolicy | null): TeamworkPermissions {
  const has = (p: TeamworkPolicy) => a === p || b === p;
  return { rescue: has('RESCUE_BLOCKED_MOVE'), convert: has('CONVERT_FAILED_ROLL_IF_POSSIBLE') };
}

function softmax(values: number[], temperature: number): number[] {
  const max = Math.max(...values);
  const exps = values.map((v) => Math.exp((v - max) / temperature));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map((e) => e / sum);
}

function sample<T>(items: readonly T[], probs: number[], random: () => number): T {
  let r = random();
  for (let i = 0; i < items.length; i++) {
    r -= probs[i]!;
    if (r <= 0) return items[i]!;
  }
  return items[items.length - 1]!;
}

function normalise(ps: number[]): number[] {
  const s = ps.reduce((a, b) => a + b, 0);
  return s > 0 ? ps.map((p) => p / s) : ps.map(() => 1 / ps.length);
}

function coreOf(v: PublicView): CoreState {
  const s = v.state;
  return {
    position: s.position,
    stamina: s.stamina,
    rope: s.rope,
    lastClippedPosition: s.lastClippedPosition,
    clippedBolts: s.clippedBolts,
    recoveryTokens: s.recoveryTokens,
    teamworkAvailable: s.teamworkAvailable,
    round: s.round,
    status: s.status,
  };
}

/** Belief over the belayer's card, from the board and the belayer's public signal only. */
export function predictBelayer(planner: Planner, s: CoreState, signal: BelayerSignal | null, signalWeight = 1): number[] {
  const table = planner.jointTable(s);
  const rational = softmax(
    BELAYER_ACTIONS.map((b) => Math.max(...table.filter((r) => r.b === b).map((r) => r.value))),
    RATIONAL_TEMPERATURE,
  );
  if (!signal) return rational;
  const lik = BELAYER_SIGNAL_LIKELIHOOD[signal];
  return normalise(BELAYER_ACTIONS.map((b, i) => rational[i]! * Math.pow(lik[b], signalWeight)));
}

/** Belief over the climber's card, from the board and the climber's public signal only. */
export function predictClimber(planner: Planner, s: CoreState, signal: ClimberSignal | null, signalWeight = 1): number[] {
  const table = planner.jointTable(s);
  const rational = softmax(
    CLIMBER_ACTIONS.map((c) => Math.max(...table.filter((r) => r.c === c).map((r) => r.value))),
    RATIONAL_TEMPERATURE,
  );
  if (!signal) return rational;
  const lik = CLIMBER_SIGNAL_LIKELIHOOD[signal];
  return normalise(CLIMBER_ACTIONS.map((c, i) => rational[i]! * Math.pow(lik[c], signalWeight)));
}

// ---------------------------------------------------------------------------------------------
// Climber
// ---------------------------------------------------------------------------------------------

export function decideClimber(view: PublicView, opts: AiOptions): AiDecision<ClimberAction, ClimberSignal> {
  if (view.role !== 'climber') throw new Error('decideClimber needs a climber view');
  if (opts.difficulty === 'beginner') return beginnerClimber(view);

  const s = coreOf(view);
  const planner = plannerFor(view.route, view.state.config);
  const partnerSignal = partnerBelayerSignal(view);
  const partnerPolicy = view.partner?.teamworkPolicy ?? null;
  const belief = predictBelayer(planner, s, partnerSignal, opts.difficulty === 'expert' ? 1 : 0.6);
  const risk = opts.riskTolerance ?? 0.5;

  const options: { action: ClimberAction; policy: TeamworkPolicy; eu: number }[] = [];
  for (const action of CLIMBER_ACTIONS) {
    if (structurallyBlocked(s, view.route, action)) continue;
    for (const policy of s.teamworkAvailable ? TEAMWORK_POLICIES : (['NEVER'] as const)) {
      const perms = permsFor(policy, partnerPolicy);
      let eu = 0;
      BELAYER_ACTIONS.forEach((b, i) => {
        const p = belief[i]!;
        if (p < 1e-4) return;
        const q = planner.q(s, action, b, perms);
        eu += p * (q.value + riskAdjustment(risk, q.fall, action));
      });
      // Prefer saving the token when spending it gains nothing.
      if (policy !== 'NEVER') eu -= 1e-6;
      options.push({ action, policy, eu });
    }
  }
  if (!options.length) options.push({ action: 'REST', policy: 'NEVER', eu: 0 });

  const chosen = pickOption(options, opts);
  return {
    action: chosen.action,
    signal: bestClimberSignal(chosen.action),
    teamworkPolicy: chosen.policy,
    reasoning: `EU ${chosen.eu.toFixed(3)}${partnerSignal ? ` reading "${partnerSignal}"` : ''}`,
  };
}

function riskAdjustment(risk: number, fall: number, action: ClimberAction): number {
  if (risk < 0.5) return -(0.5 - risk) * 0.06 * fall;
  if (risk > 0.5) {
    const progress = action === 'REACH' ? 2 : action === 'STEP' ? 1 : 0;
    return (risk - 0.5) * 0.04 * progress;
  }
  return 0;
}

function pickOption<T extends { eu: number }>(options: T[], opts: AiOptions): T {
  if (opts.difficulty === 'intermediate') {
    return sample(options, softmax(options.map((o) => o.eu), INTERMEDIATE_TEMPERATURE), opts.random);
  }
  return options.reduce((a, b) => (b.eu > a.eu ? b : a));
}

/**
 * Beginner climber: predictable and readable. It is deterministic, assumes its belayer will
 * answer its (always honest) signal, and authorises Teamwork rescues to forgive rope mistakes.
 */
function beginnerClimber(view: PublicView): AiDecision<ClimberAction, ClimberSignal> {
  const s = coreOf(view);
  const { route } = view;
  const planner = plannerFor(route, view.state.config);
  const perms = permsFor(s.teamworkAvailable ? 'RESCUE_BLOCKED_MOVE' : 'NEVER', view.partner?.teamworkPolicy ?? null);
  let best: { action: ClimberAction; eu: number } = { action: 'REST', eu: -1 };
  for (const action of CLIMBER_ACTIONS) {
    if (structurallyBlocked(s, route, action)) continue;
    const eu = Math.max(...BELAYER_ACTIONS.map((b) => planner.q(s, action, b, perms).value));
    if (eu > best.eu + 1e-9) best = { action, eu };
  }
  return {
    action: best.action,
    signal: bestClimberSignal(best.action),
    teamworkPolicy: s.teamworkAvailable ? 'RESCUE_BLOCKED_MOVE' : 'NEVER',
    reasoning: `beginner: ${best.action} expecting a helpful belay`,
  };
}

// ---------------------------------------------------------------------------------------------
// Belayer
// ---------------------------------------------------------------------------------------------

export function decideBelayer(view: PublicView, opts: AiOptions): AiDecision<BelayerAction, BelayerSignal> {
  if (view.role !== 'belayer') throw new Error('decideBelayer needs a belayer view');
  if (opts.difficulty === 'beginner') return beginnerBelayer(view);

  const s = coreOf(view);
  const planner = plannerFor(view.route, view.state.config);
  const partnerSignal = partnerClimberSignal(view);
  const partnerPolicy = view.partner?.teamworkPolicy ?? null;
  const belief = predictClimber(planner, s, partnerSignal, opts.difficulty === 'expert' ? 1 : 0.6);

  const options: { action: BelayerAction; policy: TeamworkPolicy; eu: number }[] = [];
  for (const action of BELAYER_ACTIONS) {
    for (const policy of s.teamworkAvailable ? TEAMWORK_POLICIES : (['NEVER'] as const)) {
      const perms = permsFor(policy, partnerPolicy);
      let eu = 0;
      CLIMBER_ACTIONS.forEach((c, i) => {
        const p = belief[i]!;
        if (p < 1e-4) return;
        eu += p * planner.q(s, c, action, perms).value;
      });
      if (policy !== 'NEVER') eu -= 1e-6;
      // Taking in rope is rarely right; only do it with a clear edge.
      if (action === 'TAKE_IN') eu -= 1e-4;
      options.push({ action, policy, eu });
    }
  }
  const chosen = pickOption(options, opts);
  return {
    action: chosen.action,
    signal: bestBelayerSignal(chosen.action),
    teamworkPolicy: chosen.policy,
    reasoning: `EU ${chosen.eu.toFixed(3)}${partnerSignal ? ` reading "${partnerSignal}"` : ''}`,
  };
}

/**
 * Beginner belayer: helpful and predictable. It takes the climber's signal at face value, never
 * takes rope in, and authorises Teamwork rescues so a climber's rope mistakes are forgiven.
 */
function beginnerBelayer(view: PublicView): AiDecision<BelayerAction, BelayerSignal> {
  const s = coreOf(view);
  const planner = plannerFor(view.route, view.state.config);
  const belief = predictClimber(planner, s, partnerClimberSignal(view), 3);
  const perms = permsFor(s.teamworkAvailable ? 'RESCUE_BLOCKED_MOVE' : 'NEVER', view.partner?.teamworkPolicy ?? null);
  let best: { action: BelayerAction; eu: number } = { action: 'FEED', eu: -1 };
  for (const action of BELAYER_ACTIONS) {
    if (action === 'TAKE_IN') continue;
    let eu = 0;
    CLIMBER_ACTIONS.forEach((c, i) => {
      if (belief[i]! > 1e-4) eu += belief[i]! * planner.q(s, c, action, perms).value;
    });
    if (eu > best.eu + 1e-9) best = { action, eu };
  }
  return {
    action: best.action,
    signal: bestBelayerSignal(best.action),
    teamworkPolicy: s.teamworkAvailable ? 'RESCUE_BLOCKED_MOVE' : 'NEVER',
    reasoning: `beginner: ${best.action} following the climber's lead`,
  };
}

/** The signal and Teamwork preference an AI announces at the start of a round. */
export function announce(view: PublicView, opts: AiOptions) {
  if (view.role === 'climber') {
    const d = decideClimber({ ...view, partner: null }, opts);
    return { signal: d.signal as ClimberSignal | BelayerSignal, teamworkPolicy: d.teamworkPolicy };
  }
  const d = decideBelayer({ ...view, partner: null }, opts);
  return { signal: d.signal as ClimberSignal | BelayerSignal, teamworkPolicy: d.teamworkPolicy };
}
