import type { BelayerAction, BelayerSignal, ClimberAction, ClimberSignal } from '../types.ts';

/**
 * How likely a cooperative partner is to play each card after sending a signal. AI partners use
 * these tables both to read a human's signal and to choose an honest signal for their own plan.
 */
export const CLIMBER_SIGNAL_LIKELIHOOD: Record<ClimberSignal, Record<ClimberAction, number>> = {
  MOVING_CAREFULLY: { STEP: 0.75, REACH: 0.05, CLIP: 0.1, REST: 0.1 },
  BIG_MOVE: { STEP: 0.12, REACH: 0.78, CLIP: 0.05, REST: 0.05 },
  PLANNING_CLIP: { STEP: 0.08, REACH: 0.04, CLIP: 0.8, REST: 0.08 },
  NEED_REST: { STEP: 0.08, REACH: 0.02, CLIP: 0.08, REST: 0.82 },
  NOT_SURE: { STEP: 0.25, REACH: 0.25, CLIP: 0.25, REST: 0.25 },
};

export const BELAYER_SIGNAL_LIKELIHOOD: Record<BelayerSignal, Record<BelayerAction, number>> = {
  READY_FOR_MOVEMENT: { FEED: 0.35, TAKE_IN: 0.03, BRACE: 0.12, ENCOURAGE: 0.5 },
  ROPE_AVAILABLE: { FEED: 0.8, TAKE_IN: 0.02, BRACE: 0.08, ENCOURAGE: 0.1 },
  STAY_STEADY: { FEED: 0.1, TAKE_IN: 0.1, BRACE: 0.65, ENCOURAGE: 0.15 },
  BE_CAUTIOUS: { FEED: 0.05, TAKE_IN: 0.35, BRACE: 0.55, ENCOURAGE: 0.05 },
  READY_WHEN_YOU_ARE: { FEED: 0.3, TAKE_IN: 0.1, BRACE: 0.3, ENCOURAGE: 0.3 },
};

export function bestClimberSignal(action: ClimberAction): ClimberSignal {
  const map: Record<ClimberAction, ClimberSignal> = {
    STEP: 'MOVING_CAREFULLY',
    REACH: 'BIG_MOVE',
    CLIP: 'PLANNING_CLIP',
    REST: 'NEED_REST',
  };
  return map[action];
}

export function bestBelayerSignal(action: BelayerAction): BelayerSignal {
  const map: Record<BelayerAction, BelayerSignal> = {
    FEED: 'ROPE_AVAILABLE',
    TAKE_IN: 'BE_CAUTIOUS',
    BRACE: 'STAY_STEADY',
    ENCOURAGE: 'READY_FOR_MOVEMENT',
  };
  return map[action];
}
