import { announce, decideBelayer, decideClimber, type AiDifficulty } from '../engine/ai/agent.ts';
import { createMatchCore, declare, forfeitMatch, submit } from '../engine/match.ts';
import { mulberry32, hashString, randomSeed } from '../engine/rng.ts';
import type { BelayerSignal, ClimberSignal, Role, Submission, TeamworkPolicy } from '../engine/types.ts';
import { buildPublicView, type PublicView } from '../engine/view.ts';
import { getRoute } from '../data/routes/index.ts';
import type { LocalMatchRecord, LocalMode, LocalPlayer } from './db.ts';

/**
 * Offline game logic. Pure functions from record to record; the React hook persists them.
 * AI partners only ever see `buildPublicView` output — never the human's pending action.
 */

export const otherRole = (r: Role): Role => (r === 'climber' ? 'belayer' : 'climber');

export function newId(): string {
  return `local-${Date.now().toString(36)}-${randomSeed().slice(0, 8)}`;
}

export interface NewLocalGame {
  mode: LocalMode;
  routeId: string;
  /** Solo: which role the human plays. */
  humanRole?: Role;
  difficulty?: AiDifficulty;
  names?: Partial<Record<Role, string>>;
}

const AI_NAMES: Record<Role, string> = { climber: 'Juniper (AI)', belayer: 'Rowan (AI)' };

export function createLocalMatch(opts: NewLocalGame): LocalMatchRecord {
  const route = getRoute(opts.routeId);
  const now = Date.now();
  const human = opts.humanRole ?? 'climber';
  const player = (role: Role): LocalPlayer => {
    if (opts.mode === 'pass_and_play') return { kind: 'human', name: opts.names?.[role] || (role === 'climber' ? 'Climber' : 'Belayer') };
    return role === human
      ? { kind: 'human', name: opts.names?.[role] || 'You' }
      : { kind: 'ai', name: AI_NAMES[role], difficulty: opts.difficulty ?? 'intermediate' };
  };
  return {
    id: newId(),
    mode: opts.mode,
    routeId: route.id,
    createdAt: now,
    updatedAt: now,
    players: { climber: player('climber'), belayer: player('belayer') },
    core: createMatchCore(route, randomSeed()),
    lastResult: null,
    revealSeen: true,
    activeRole: opts.mode === 'pass_and_play' ? 'climber' : null,
    handoff: opts.mode === 'pass_and_play',
    recorded: false,
  };
}

export function humanRoleOf(r: LocalMatchRecord): Role | null {
  if (r.mode !== 'solo') return null;
  return r.players.climber.kind === 'human' ? 'climber' : 'belayer';
}

/** Pass-and-play alternates who chooses first: climber on odd rounds, belayer on even rounds. */
export function firstRoleForRound(round: number): Role {
  return round % 2 === 1 ? 'climber' : 'belayer';
}

/**
 * Work the AI still has to do before the human can continue, described as plain data so it can
 * run in a Web Worker. The task carries only public information.
 */
export interface AiTask {
  kind: 'announce' | 'submit';
  role: Role;
  view: PublicView;
  difficulty: AiDifficulty;
  randomSeed: string;
  /** Guards against applying a stale answer to a newer record. */
  version: number;
}

export function pendingAiTask(r: LocalMatchRecord): AiTask | null {
  if (r.mode !== 'solo' || r.core.state.status !== 'in_progress') return null;
  const human = humanRoleOf(r);
  if (!human) return null;
  const ai = otherRole(human);
  if (r.core.pending[ai]) return null;
  const route = getRoute(r.routeId);
  const base = {
    role: ai,
    difficulty: r.players[ai].difficulty ?? ('intermediate' as AiDifficulty),
    randomSeed: `${r.core.seed}:ai:${r.core.state.round}:${r.core.version}`,
    version: r.core.version,
  };
  if (r.core.pending[human]) {
    // The human has committed: the AI decides, reading only the human's public declaration.
    return { ...base, kind: 'submit', view: buildPublicView(r.core.state, route, ai, r.core.declarations[human]) };
  }
  if (!r.core.declarations[ai]) {
    // Start of a round: the AI announces its signal first so the human can read it.
    return { ...base, kind: 'announce', view: buildPublicView(r.core.state, route, ai, null) };
  }
  return null;
}

export type AiAnswer =
  | { kind: 'announce'; signal: ClimberSignal | BelayerSignal | null; teamworkPolicy: TeamworkPolicy }
  | { kind: 'submit'; submission: Submission };

/** Run an AI task. Pure and deterministic; used directly in tests and inside the worker. */
export function runAiTask(task: AiTask): AiAnswer {
  const opts = { difficulty: task.difficulty, random: mulberry32(hashString(task.randomSeed)) };
  if (task.kind === 'announce') {
    const a = announce(task.view, opts);
    return { kind: 'announce', signal: a.signal, teamworkPolicy: a.teamworkPolicy };
  }
  if (task.role === 'climber') {
    const d = decideClimber(task.view, opts);
    return { kind: 'submit', submission: { role: 'climber', action: d.action, signal: d.signal, teamworkPolicy: d.teamworkPolicy } };
  }
  const d = decideBelayer(task.view, opts);
  return { kind: 'submit', submission: { role: 'belayer', action: d.action, signal: d.signal, teamworkPolicy: d.teamworkPolicy } };
}

/** Apply an AI answer if the record has not moved on since the task was created. */
export function applyAiAnswer(r: LocalMatchRecord, task: AiTask, answer: AiAnswer): LocalMatchRecord {
  if (r.core.version !== task.version) return r;
  if (answer.kind === 'announce') {
    return { ...r, core: declare(r.core, task.role, { signal: answer.signal, teamworkPolicy: answer.teamworkPolicy }) };
  }
  // Keep the announced signal: it is already public and the human may have relied on it.
  const announced = r.core.declarations[task.role];
  const sub = { ...answer.submission, signal: announced ? announced.signal : answer.submission.signal } as Submission;
  return commit(r, sub);
}

/** Record a human submission. Solo games then need `pendingAiTask` for the AI's card. */
export function submitHuman(r: LocalMatchRecord, sub: Submission): LocalMatchRecord {
  return commit(r, sub);
}

function commit(r: LocalMatchRecord, sub: Submission): LocalMatchRecord {
  const route = getRoute(r.routeId);
  const out = submit(r.core, route, sub, r.core.state.round);
  let next: LocalMatchRecord = { ...r, core: out.match, updatedAt: Date.now() };
  if (out.resolved) {
    next = {
      ...next,
      lastResult: out.resolved,
      revealSeen: false,
      activeRole: r.mode === 'pass_and_play' ? firstRoleForRound(out.match.state.round) : null,
      handoff: false,
    };
  } else if (r.mode === 'pass_and_play') {
    // Hand the device to the other player; the next screen hides everything.
    next = { ...next, activeRole: otherRole(sub.role), handoff: true };
  }
  return next;
}

/** Synchronously finish any outstanding AI work (tests and worker-less fallback). */
export function settleAiSync(r: LocalMatchRecord): LocalMatchRecord {
  let cur = r;
  for (let i = 0; i < 4; i++) {
    const task = pendingAiTask(cur);
    if (!task) return cur;
    cur = applyAiAnswer(cur, task, runAiTask(task));
  }
  return cur;
}

export function markRevealSeen(r: LocalMatchRecord): LocalMatchRecord {
  return {
    ...r,
    revealSeen: true,
    handoff: r.mode === 'pass_and_play' && r.core.state.status === 'in_progress',
    updatedAt: Date.now(),
  };
}

export function acceptHandoff(r: LocalMatchRecord): LocalMatchRecord {
  return { ...r, handoff: false, updatedAt: Date.now() };
}

export function forfeitLocal(r: LocalMatchRecord): LocalMatchRecord {
  return { ...r, core: forfeitMatch(r.core), updatedAt: Date.now() };
}

/** A fresh game with the same players, route and mode. */
export function rematchLocal(r: LocalMatchRecord, routeId = r.routeId): LocalMatchRecord {
  const human = humanRoleOf(r);
  const ai = human ? otherRole(human) : null;
  const difficulty = ai ? r.players[ai].difficulty : undefined;
  return createLocalMatch({
    mode: r.mode,
    routeId,
    ...(human ? { humanRole: human } : {}),
    ...(difficulty ? { difficulty } : {}),
    names:
      r.mode === 'pass_and_play'
        ? { climber: r.players.climber.name, belayer: r.players.belayer.name }
        : human
          ? { [human]: r.players[human].name }
          : {},
  });
}
