import type {
  BelayerSignal,
  ClimberSignal,
  GameState,
  PublicDeclaration,
  Role,
  RouteDefinition,
  Submission,
} from './types.ts';

/**
 * Everything a player — human or AI — is allowed to know when choosing a card.
 * It deliberately has no field that can hold the partner's committed action.
 */
export interface PublicView {
  readonly state: GameState;
  readonly route: RouteDefinition;
  readonly role: Role;
  /** The partner's public declaration this round, if they have made one. */
  readonly partner: PublicDeclaration | null;
}

/** Strip a submission down to what may be shown to the other player before resolution. */
export function declarationOf(sub: Submission | null | undefined): PublicDeclaration | null {
  if (!sub) return null;
  return { signal: sub.signal, teamworkPolicy: sub.teamworkPolicy, committed: true };
}

export function buildPublicView(
  state: GameState,
  route: RouteDefinition,
  role: Role,
  partner: PublicDeclaration | null,
): PublicView {
  // Copy only whitelisted fields so an object that happens to carry extra properties
  // (for example a full Submission) can never leak its action through the view.
  const safePartner: PublicDeclaration | null = partner
    ? { signal: partner.signal, teamworkPolicy: partner.teamworkPolicy, committed: partner.committed }
    : null;
  return { state, route, role, partner: safePartner };
}

export const partnerClimberSignal = (v: PublicView) =>
  v.role === 'belayer' ? ((v.partner?.signal ?? null) as ClimberSignal | null) : null;
export const partnerBelayerSignal = (v: PublicView) =>
  v.role === 'climber' ? ((v.partner?.signal ?? null) as BelayerSignal | null) : null;
