import { ROPE_REQUIRED, STAMINA_COST } from './config.ts';
import { isBolt } from './routes.ts';
import type { BlockReason, ClimberAction, GameStatus, RouteDefinition } from './types.ts';

export interface LegalityState {
  position: number;
  stamina: number;
  clippedBolts: readonly number[];
  status: GameStatus;
}

/**
 * Why a climber action would be blocked given a rope value, or null if it is legal.
 * Order matters: structural problems are reported before resource shortages, and stamina before
 * rope, so that a Teamwork rescue (which only adds rope) is only considered for rope-only blocks.
 */
export function blockReason(
  state: LegalityState,
  route: RouteDefinition,
  action: ClimberAction,
  rope: number,
): BlockReason | null {
  if (state.status !== 'in_progress') return 'game_over';
  switch (action) {
    case 'REST':
      return null;
    case 'STEP':
      if (state.position + 1 > route.length) return 'beyond_finish';
      break;
    case 'REACH':
      if (state.position + 2 > route.length) return 'beyond_finish';
      break;
    case 'CLIP':
      if (!isBolt(route, state.position)) return 'not_at_bolt';
      if (state.clippedBolts.includes(state.position)) return 'already_clipped';
      break;
  }
  if (state.stamina < STAMINA_COST[action]) return 'not_enough_stamina';
  if (rope < ROPE_REQUIRED[action]) return 'not_enough_rope';
  return null;
}

/** Actions that can never be legal this round regardless of what the belayer does. */
export function structurallyBlocked(
  state: LegalityState,
  route: RouteDefinition,
  action: ClimberAction,
): BlockReason | null {
  const reason = blockReason(state, route, action, Number.POSITIVE_INFINITY);
  return reason;
}

export const BLOCK_REASON_TEXT: Record<BlockReason, string> = {
  not_enough_rope: 'There was not enough rope available for that move.',
  not_enough_stamina: 'The climber did not have enough stamina for that move.',
  beyond_finish: 'That move would go past the finishing anchor.',
  not_at_bolt: 'There is no bolt at the climber’s position to clip.',
  already_clipped: 'That bolt is already clipped.',
  game_over: 'The route is already finished.',
};
