import type { DiceSource } from './types.ts';

/** 32-bit FNV-1a hash of a string. Used to derive deterministic per-round seeds. */
export function hashString(input: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Mulberry32: small, fast, well-distributed PRNG. Returns floats in [0, 1). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function diceFromRandom(random: () => number): DiceSource {
  return { rollD6: () => 1 + Math.floor(random() * 6) };
}

/**
 * Dice for one round of one game. The same (secret seed, round) pair always yields the same
 * rolls, which makes server-side resolution idempotent: a retried resolution reproduces the
 * identical outcome instead of re-rolling.
 */
export function diceForRound(seed: string, round: number): DiceSource {
  return diceFromRandom(mulberry32(hashString(`${seed}:round:${round}`)));
}

/** Fixed sequence of rolls for tests. Throws if the engine asks for more rolls than provided. */
export function scriptedDice(rolls: number[]): DiceSource & { remaining(): number } {
  const queue = [...rolls];
  return {
    rollD6() {
      const next = queue.shift();
      if (next === undefined) throw new Error('scriptedDice: no rolls left');
      if (!Number.isInteger(next) || next < 1 || next > 6) throw new Error(`scriptedDice: invalid roll ${next}`);
      return next;
    },
    remaining: () => queue.length,
  };
}

/** Generate a random seed string. Uses crypto when available (browser, Deno, Node). */
export function randomSeed(): string {
  const c = (globalThis as { crypto?: { getRandomValues?: (a: Uint32Array) => Uint32Array } }).crypto;
  if (c?.getRandomValues) {
    const buf = new Uint32Array(4);
    c.getRandomValues(buf);
    return Array.from(buf, (n) => n.toString(16).padStart(8, '0')).join('');
  }
  return `${Date.now().toString(16)}${Math.floor(Math.random() * 1e12).toString(16)}`;
}
