export const ROUTES: readonly RouteDefinition[] = [FIRST_ASCENT, RAVENS_REACH, THE_WIDOWMAKER].map(assertValidRoute);

const BY_ID = new Map(ROUTES.map((r) => [r.id, r]));

export function getRoute(id: string): RouteDefinition {
  const route = BY_ID.get(id);
  if (!route) throw new Error(`Unknown route: ${id}`);
  return route;
}

export function findRoute(id: string): RouteDefinition | undefined {
  return BY_ID.get(id);
}
